declare_lint ! { #[doc = " The `opaque_hidden_inferred_bound` lint detects cases in which nested"] #[doc = " `impl Trait` in associated type bounds are not written generally enough"] #[doc = " to satisfy the bounds of the associated type."] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " This functionality was removed in #97346, but then rolled back in #99860"] #[doc = " because it caused regressions."] #[doc = ""] #[doc = " We plan on reintroducing this as a hard error, but in the meantime,"] #[doc = " this lint serves to warn and suggest fixes for any use-cases which rely"] #[doc = " on this behavior."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(type_alias_impl_trait)]"] #[doc = ""] #[doc = " trait Duh {}"] #[doc = ""] #[doc = " impl Duh for i32 {}"] #[doc = ""] #[doc = " trait Trait {"] #[doc = "     type Assoc: Duh;"] #[doc = " }"] #[doc = ""] #[doc = " impl<F: Duh> Trait for F {"] #[doc = "     type Assoc = F;"] #[doc = " }"] #[doc = ""] #[doc = " type Tait = impl Sized;"] #[doc = ""] #[doc = " #[define_opaque(Tait)]"] #[doc = " fn test() -> impl Trait<Assoc = Tait> {"] #[doc = "     42"] #[doc = " }"] #[doc = ""] #[doc = " fn main() {}"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " In this example, `test` declares that the associated type `Assoc` for"] #[doc = " `impl Trait` is `impl Sized`, which does not satisfy the bound `Duh`"] #[doc = " on the associated type."] #[doc = ""] #[doc = " Although the hidden type, `i32` does satisfy this bound, we do not"] #[doc = " consider the return type to be well-formed with this lint. It can be"] #[doc = " fixed by changing `Tait = impl Sized` into `Tait = impl Sized + Duh`."] pub OPAQUE_HIDDEN_INFERRED_BOUND , Warn , "detects the use of nested `impl Trait` types in associated type bounds that are not general enough" }